type StayKind = "hotels" | "hostels";

const neighborhoodTourismSources: Record<string, ListSource> = {
  Shibuya: source("GO TOKYO - Shibuya official area guide", "https://www.gotokyo.org/en/destinations/western-tokyo/shibuya/index.html"),
  Shinjuku: source("GO TOKYO - Shinjuku official area guide", "https://www.gotokyo.org/en/destinations/western-tokyo/shinjuku/index.html"),
  Ginza: source("GO TOKYO - Ginza official area guide", "https://www.gotokyo.org/en/destinations/central-tokyo/ginza/index.html"),
  Asakusa: source("GO TOKYO - Asakusa official area guide", "https://www.gotokyo.org/en/destinations/eastern-tokyo/asakusa/index.html"),
  Roppongi: source("GO TOKYO - Roppongi official area guide", "https://www.gotokyo.org/en/destinations/southern-tokyo/roppongi/index.html"),
};

const hotelSourceBackbone = [
  source("GO TOKYO - accommodation overview", "https://www.gotokyo.org/en/plan/accommodations/index.html"),
  source("Conde Nast Traveler - best hotels in Tokyo", "https://www.cntraveler.com/gallery/best-hotels-in-tokyo"),
  source("MICHELIN Guide - Tokyo hotels", "https://guide.michelin.com/us/en/hotels-stays/tokyo"),
  source("Google Travel - Tokyo hotels", "https://www.google.com/travel/hotels/Tokyo"),
  source("Booking.com - Tokyo hotels", "https://www.booking.com/city/jp/tokyo.html"),
  source("Tripadvisor - Tokyo hotels", "https://www.tripadvisor.com/Hotels-g298184-Tokyo_Tokyo_Prefecture_Kanto-Hotels.html"),
];

const hostelSourceBackbone = [
  source("GO TOKYO - accommodation overview", "https://www.gotokyo.org/en/plan/accommodations/index.html"),
  source("Hostelworld - Tokyo hostels", "https://www.hostelworld.com/hostels/asia/japan/tokyo/"),
  source("Hostelgeeks - best hostels in Tokyo", "https://hostelgeeks.com/best-hostels-in-tokyo-japan/"),
  source("The Broke Backpacker - best hostels in Tokyo", "https://www.thebrokebackpacker.com/best-hostels-in-tokyo-japan/"),
  source("Google Travel - Tokyo hostels", "https://www.google.com/travel/hotels/Tokyo?q=hostels%20tokyo"),
  source("Booking.com - Tokyo hostels", "https://www.booking.com/hostels/city/jp/tokyo.html"),
];

function neighborhoodStaySources(
  neighborhood: keyof typeof neighborhoodTourismSources,
  kind: StayKind,
  propertySources: Array<[string, string]>,
): ListSource[] {
  return [
    neighborhoodTourismSources[neighborhood],
    source(`Google Maps - ${neighborhood} ${kind}`, maps(`${neighborhood} Tokyo ${kind}`)),
    ...(kind === "hotels" ? hotelSourceBackbone : hostelSourceBackbone),
    ...propertySources.map(([name, url]) => source(`${name} official property source`, url)),
  ];
}

function findStop(stops: GuideStop[], id: string) {
  const match = stops.find((item) => item.id === id);
  if (!match) throw new Error(`Missing Tokyo guide stop: ${id}`);
  return match;
}

function retellStop(base: GuideStop, id: string, description: string, attributeTags: string[] = []): GuideStop {
  return {
    ...base,
    id,
    description,
    attributeTags: [...new Set([...(base.attributeTags ?? []), ...attributeTags])],
  };
}

